CREATE OR REPLACE FUNCTION public.category_lifecycle_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE payload jsonb; affected integer; links uuid[]; original_ids uuid[]; p uuid; t uuid; c uuid;
BEGIN
 IF TG_OP='DELETE' THEN payload=to_jsonb(OLD); ELSE payload=to_jsonb(NEW); END IF;
 IF TG_TABLE_NAME='action_receipts' AND payload->>'operation' LIKE 'evidence.lifecycle.%' THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 p=(payload->>'product_id')::uuid; t=(payload->>'tenant_id')::uuid;
 c=(payload->>'category_id')::uuid;
 IF p IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.artifact_versions a WHERE a.tenant_id=t AND a.category_id=c AND a.product_id IS NULL
 ) AND NOT EXISTS (
  SELECT 1 FROM public.uploaded_originals o WHERE o.tenant_id=t AND o.category_id=c AND o.product_id IS NULL
 ) THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 links=public.lifecycle_payload_links(payload);
 SELECT COALESCE(array_agg(a.original_id) FILTER (WHERE a.original_id IS NOT NULL),'{}')
 INTO original_ids FROM public.artifact_versions a
 WHERE a.tenant_id=t AND a.category_id=c AND a.product_id IS NULL AND a.id=ANY(links);
 IF p IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.artifact_versions a WHERE a.tenant_id=t AND a.category_id=c
   AND a.product_id IS NULL AND a.id=ANY(links)
 ) AND NOT EXISTS (
  SELECT 1 FROM public.uploaded_originals o WHERE o.tenant_id=t AND o.category_id=c
   AND o.product_id IS NULL AND o.id=ANY(links)
 ) THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 UPDATE public.categories SET lifecycle_epoch=lifecycle_epoch+1 WHERE id=c AND tenant_id=t;
 GET DIAGNOSTICS affected = ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'Reference category gate unavailable' USING ERRCODE='23514'; END IF;
 IF TG_OP<>'DELETE' AND EXISTS (
  SELECT 1 FROM public.lifecycle_objects o WHERE o.tenant_id=t AND o.category_id=c
   AND o.product_id IS NULL AND o.id=ANY(links || original_ids)
   AND ((o.state->'value'->>'pending_intent_id') IS NOT NULL
    OR o.state->'value'->>'disposition' IN ('quarantined','unknown','purged'))
 ) THEN RAISE EXCEPTION 'Pending category original prohibits new references' USING ERRCODE='23514', CONSTRAINT='category_source_reference_fence'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.kernel_scope_failed(rid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
      DECLARE r agent_runs; cid uuid; prior_actor text; lost boolean;
      BEGIN
        SELECT * INTO r FROM agent_runs WHERE id=rid
          AND tenant_id=NULLIF(current_setting('pdos.tenant_id',true),'')::uuid
          AND requester_id=scope_requester() AND requester_id=scope_actor()
          AND category_id IS NOT DISTINCT FROM
            NULLIF(current_setting('pdos.category_id',true),'')::uuid FOR UPDATE;
        IF NOT FOUND OR r.reverted_at IS NOT NULL OR r.state IN ('completed','partial','failed','cancelled') THEN RETURN false; END IF;
        prior_actor=current_setting('pdos.actor_id',true);
        PERFORM set_config('pdos.actor_id',r.writer_id::text,true);
        lost=NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id
            AND p.id=r.writer_id AND p.kind='agent' AND p.active)
          OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id
            AND p.id=r.requester_id AND p.kind='human' AND p.active)
          OR (r.category_id IS NOT NULL AND NOT category_access(r.tenant_id,r.category_id))
          OR NOT kernel_read_set_visible(r.tenant_id,r.category_id,r.read_sources)
          OR (r.validation_budget_id IS NOT NULL AND NOT EXISTS(
            SELECT 1 FROM agent_validation_budgets b WHERE b.id=r.validation_budget_id
              AND b.tenant_id=r.tenant_id AND b.active))
          OR (r.product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM products p
            WHERE p.id=r.product_id AND p.tenant_id=r.tenant_id AND p.category_id=r.category_id
              AND (p.visibility='category' OR p.owner_id=r.requester_id OR EXISTS(
                SELECT 1 FROM object_audiences a WHERE a.tenant_id=p.tenant_id
                  AND a.category_id=p.category_id AND a.object_type='products'
                  AND a.subject_id=p.id AND a.owner_id=p.owner_id AND a.principal_id=r.requester_id))));
        IF NOT COALESCE(lost,true) THEN
          PERFORM set_config('pdos.actor_id',prior_actor,true); RETURN false;
        END IF;
        FOR cid IN SELECT id FROM agent_tool_calls WHERE tenant_id=r.tenant_id
            AND run_id=r.id AND state='started' ORDER BY id LOOP
          PERFORM kernel_release_call(r.id,cid,'FORBIDDEN_SCOPE',true,0,NULL);
        END LOOP;
        PERFORM set_config('pdos.actor_id',prior_actor,true);
        UPDATE agent_runs SET state='failed',error_code='FORBIDDEN_SCOPE',result=NULL WHERE id=r.id;
        RETURN true;
      END $function$

CREATE OR REPLACE FUNCTION public.lifecycle_reference_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE payload JSONB; old_payload JSONB; p UUID; t UUID; c UUID;
      BEGIN
        IF TG_OP='DELETE' THEN payload=to_jsonb(OLD); ELSE payload=to_jsonb(NEW); END IF;
        IF TG_OP='UPDATE' THEN
          old_payload=to_jsonb(OLD);
          IF ROW(payload->>'product_id',payload->>'tenant_id',payload->>'category_id') IS DISTINCT FROM
             ROW(old_payload->>'product_id',old_payload->>'tenant_id',old_payload->>'category_id') THEN
            RAISE EXCEPTION 'Reference scope cannot be reassigned';
          END IF;
        END IF;
        -- Lifecycle receipts document retention decisions, not consuming business references.
        IF TG_TABLE_NAME='action_receipts' AND payload->>'operation' LIKE 'evidence.lifecycle.%' THEN
          IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
        END IF;
        p=(payload->>'product_id')::uuid; t=(payload->>'tenant_id')::uuid;
        c=(payload->>'category_id')::uuid;
        IF p IS NULL THEN
          IF TG_OP<>'DELETE' AND EXISTS (
            SELECT 1 FROM lifecycle_objects o WHERE o.product_id IS NULL AND o.category_id=c AND o.tenant_id=t
            AND ((o.state->'value'->>'pending_intent_id') IS NOT NULL
              OR o.state->'value'->>'disposition' IN ('quarantined','unknown','purged'))
            AND position(o.id::text in payload::text)>0
          ) THEN RAISE EXCEPTION 'Pending or isolated original prohibits new references'; END IF;
          IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
        END IF;
        PERFORM 1 FROM products WHERE id=p AND tenant_id=t FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Reference product gate unavailable'; END IF;
        IF TG_OP<>'DELETE' AND EXISTS (
          SELECT 1 FROM lifecycle_objects o WHERE o.product_id=p AND o.tenant_id=t
          AND ((o.state->'value'->>'pending_intent_id') IS NOT NULL
               OR o.state->'value'->>'disposition' IN ('quarantined','unknown','purged'))
          AND position(o.id::text in payload::text)>0
        ) THEN RAISE EXCEPTION 'Pending or isolated original prohibits new references'; END IF;
        UPDATE products SET lifecycle_epoch=lifecycle_epoch+1 WHERE id=p AND tenant_id=t;
        IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
      END $function$

CREATE OR REPLACE FUNCTION public.lifecycle_reference_summary(t uuid, c uuid, p uuid, roots uuid[])
 RETURNS TABLE(object_id uuid, reference_count integer, formal_history boolean, read_version bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE tables text[]=ARRAY['action_receipts','actual_configurations','artifact_versions','audit_entries','bom_lines','bom_revisions','build_authorization_decisions','build_current_authorizations','build_current_execution_assessments','build_execution_assessments','build_lots','build_operational_current','build_operational_facts','build_readiness','build_starts','builds','capa_current_observations','capa_current_verification_rules','capa_named_verification_reviews','capa_observation_facts','capa_remediation_links','capa_verification_evidence','capa_verification_rule_facts','change_approval_records','change_dependency_clocks','change_graph_captures','change_implementation_captures','change_implementation_records','change_order_records','change_request_currents','change_request_versions','claim_consumptions','claims','controlled_change_coverage_currents','controlled_change_coverage_facts','controlled_change_policy_currents','controlled_change_policy_facts','controlled_change_selection_currents','controlled_change_selection_facts','cost_current_inputs','cost_estimates','cost_input_snapshots','cost_source_captures','definition_revisions','definition_sources','definition_specs','engineering_configurations','manufacturing_baseline_document_links','manufacturing_preparation_currents','manufacturing_preparation_versions','measurement_import_captures','operational_material_holds','operational_resource_occupancies','original_scan_requests','original_scan_results','original_security','outbox_events','parts','plan_proposals','plan_revisions','process_revisions','product_variants','professional_authority_current','professional_authority_facts','project_product_links','project_tasks','project_work_packages','projects','quality_current_issues','quality_current_policies','quality_event_failure_links','quality_failure_maps','quality_issue_versions','quality_policy_facts','request_keys','runs','sample_allocations','sample_current_readiness','sample_readiness_facts','sample_run_usages','sample_units','sample_usage_sentinels','supply_current_snapshots','supply_kit_projections','supply_snapshots','supply_source_captures','task_dependencies','test_measurements','test_resource_current','test_resource_facts','test_resource_reservations','test_result_actions','test_result_projections','uploaded_originals','variant_revisions','verification_actual_method_applicabilities','verification_actual_method_batches','verification_current_actual_methods','verification_current_formal_requests','verification_current_preparations','verification_current_runs','verification_formal_requests','verification_handoff_facts','verification_launch_facts','verification_method_applicabilities','verification_preparations','verification_run_identities','verification_run_versions','verification_window_proposals','work_requests']; table_name text; payload jsonb;
 graph jsonb[]='{}'; controls uuid[]; reached uuid[]='{}'; selected integer[]='{}';
 node jsonb; links uuid[]; row_id uuid; oid uuid; i integer; changed boolean;
BEGIN
 IF NOT category_access(t,c,false) OR (p IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM products WHERE id=p AND tenant_id=t AND category_id=c
 )) THEN RETURN; END IF;
 SELECT COALESCE(array_agg(id),'{}') INTO controls FROM action_receipts
  WHERE tenant_id=t AND category_id=c AND product_id IS NOT DISTINCT FROM p AND operation LIKE 'evidence.lifecycle.%';
 FOREACH table_name IN ARRAY tables LOOP
  FOR payload IN EXECUTE CASE WHEN table_name=ANY(ARRAY['audit_entries','outbox_events','request_keys'])
   THEN format('SELECT to_jsonb(x) FROM public.%I x JOIN action_receipts r ON r.id=x.receipt_id AND r.tenant_id=x.tenant_id WHERE x.tenant_id=$1 AND ( $2 IS NULL OR r.product_id=$2 ) AND r.category_id=$3',table_name)
   ELSE format('SELECT to_jsonb(x) FROM public.%I x WHERE tenant_id=$1 AND ( $2 IS NULL OR product_id=$2 ) AND category_id=$3',table_name)
   END USING t,p,c LOOP
   IF (payload->>'receipt_id')::uuid=ANY(controls) OR
     (table_name='action_receipts' AND payload->>'operation' LIKE 'evidence.lifecycle.%') THEN CONTINUE; END IF;
   graph=array_append(graph,jsonb_build_object('table',table_name,'id',payload->>'id',
     'links',to_jsonb(lifecycle_payload_links(payload))));
  END LOOP;
 END LOOP;
 IF p IS NULL THEN
  SELECT lifecycle_epoch INTO read_version FROM categories WHERE id=c AND tenant_id=t;
 ELSE
  SELECT lifecycle_epoch INTO read_version FROM products WHERE id=p AND tenant_id=t AND category_id=c;
 END IF;
 FOREACH oid IN ARRAY roots LOOP
  IF NOT (
   EXISTS(SELECT 1 FROM upload_attempts WHERE id=oid AND tenant_id=t AND category_id=c AND product_id IS NOT DISTINCT FROM p AND owner_id=scope_requester()) OR
   EXISTS(SELECT 1 FROM uploaded_originals WHERE id=oid AND tenant_id=t AND category_id=c AND product_id IS NOT DISTINCT FROM p AND owner_id=scope_requester()) OR
   EXISTS(SELECT 1 FROM lifecycle_objects WHERE id=oid AND tenant_id=t AND category_id=c AND product_id IS NOT DISTINCT FROM p AND owner_id=scope_requester())
  ) THEN CONTINUE; END IF;
  object_id=oid; reached=ARRAY[oid]; selected='{}'; changed=true;
 WHILE changed LOOP
  changed=false;
  IF cardinality(graph)>0 THEN
   FOR i IN 1..cardinality(graph) LOOP
    IF i=ANY(selected) THEN CONTINUE; END IF;
    node=graph[i]; row_id=(node->>'id')::uuid;
    SELECT COALESCE(array_agg(v::uuid),'{}') INTO links FROM jsonb_array_elements_text(node->'links') AS x(v);
    IF row_id=oid OR links && reached THEN
     selected=array_append(selected,i);
     IF row_id IS NOT NULL AND NOT row_id=ANY(reached) THEN reached=array_append(reached,row_id); END IF;
     changed=true;
    END IF;
   END LOOP;
  END IF;
 END LOOP;
 reference_count=cardinality(selected); formal_history=false;
 FOREACH i IN ARRAY selected LOOP
  IF NOT (graph[i]->>'table'=ANY(ARRAY['uploaded_originals','artifact_versions','original_security',
    'original_scan_requests','original_scan_results','outbox_events','audit_entries'])) THEN
   formal_history=true; EXIT;
  END IF;
 END LOOP;
 RETURN NEXT;
 END LOOP;
END $function$
